    const modelGroups = CS.ui.models.length ? CS.ui.providers.filter(p => CS.ui.models.some(m => m.providerId === p.id)).map(p => `<div>${CS.ui.models.filter(m => m.providerId === p.id).map(m => `<div class="setting-row compact"><div><h3>${e(m.model)}</h3><p>${e(m.providerName || p.name)}</p></div><span class="row gap-6">${m.isDefault ? '' : iconBtn('pick-model','check','设为默认',`data-id="${e(m.id)}"`)}${iconBtn('edit-model','edit','编辑模型',`data-id="${e(m.id)}"`)}${iconBtn('delete-model','trash','删除模型',`data-id="${e(m.id)}"`)}${iconBtn('add-model','plus','在此服务商下添加模型',`data-id="${e(p.id)}"`)}</span></div>`).join('')}</div>`).join('') : `<div class="setting-row"><div><h3>尚未添加模型</h3><p>在服务商下添加模型后，可在此管理。</p></div></div>`;
